def solve(inputs: dict) -> float:
    A, B, C, D, MOD, K = inputs['A'], inputs['B'], inputs['C'], inputs['D'], inputs['MOD'], inputs['K']
    M = [[A, B], [C, D]]
    result = M
    for _ in range(1, K):
        result = [[sum(result[0][i] * M[j][k] for k in range(2)) % MOD for j in range(2)] for i in range(2)]
    return sum(sum(row) for row in result)

